// Cave flyer: a one-button game in the 8-bit palette mode. Hold to rise,
// let go to fall, and thread the Lumen through an endless cave that gets
// narrower and faster the further it goes. Catch the gems on the way.
//
// One button is anything: a finger or a click anywhere, any key, any GPIO
// button. So it plays on a frame with a single key as well as on a touch
// screen or in a browser. P or Escape pauses, and so does the button in the
// top right corner. The cave scrolls a column at a time with one native
// copyWithin of the cells (game.ts).
import { clip, target, textCenter, title } from './gfx'
import { START, TAP, dragging, handle, held as heldNow, lastTapX, lastTapY, press, releaseAll, setButtons, setHitTest, take } from './input'
import {
  UI_ACCENT, UI_BLINK, UI_SHADOW, UI_TEXT, UI_TITLE, addScore, blink, cellSize, choice, clockReset, dialog,
  drawGameOver, drawPause, drawScores, drawSlowCard, fastScreen, fitScale, highContrast, pauseChoice, readScores,
  reseed, stepsDue, uiColors,
} from './ui'
import { CAVES, GEM, GLOW, HUD_TEXT, gameColors, theme, trailColors } from './art'
import { FIELD, PAUSE_BOX, S, drawHud, frame, hover, newRun, resume, setBest, setField, snapshot, stillCave, takeSparkle, trailHead } from './game'

const STEP_MS = 1000 / 60
const IDLE_MS = 30000

let cells: Uint8Array | null = null
let saved: Uint8Array | null = null // the field under the pause dialog
let cols = 0
let rows = 0
let px = 4
let width = 0
let height = 0
const pal = new Uint32Array(256)
const opts = { width: 1, height: 1, pixelSize: 1 }

type Mode = 'title' | 'play' | 'pause' | 'over' | 'slow'
let mode: Mode = 'title'
let idleFrom = 0
let scores: number[] = []
let rank = -1
let overAt = 0
let overReady = false
let snapAt = 0
let titlePage = -1

let settingsAt = 0
let layoutKey = ''
let hc = false
let fast = true
let difficulty = 1
let gems = true
let cave = 0
let colorKey = ''
let round = false // drawing a round panel's whole canvas (context.round)

// Every key is the button, but P and Escape pause.
function keys(code: string): number {
  return code === 'KeyP' || code === 'Escape' ? START : 16
}

export function get(app, context) {
  const now = Date.now()
  const w = context.imageWidth || app.frame.width
  const h = context.imageHeight || app.frame.height
  if (!cells || w !== width || h !== height || now - settingsAt > 1000) settings(app, w, h, now, context.round === true)
  if (mode === 'slow') {
    frameos.setNextSleep(3600)
    return frameos.pixels(cells!, pal, opts)
  }
  let pressed = take()
  // The button: anything held but pause, or a finger down anywhere on the cave.
  const down = (heldNow() & ~START) !== 0 || dragging() >= 0
  if (mode === 'title') {
    if (pressed & ~START) {
      start(now)
      pressed = 0
    } else titleScreen(now)
  } else if (mode === 'pause') {
    let pick = 0
    if (pressed & TAP) pick = pauseChoice(lastTapX() / px, lastTapY() / px)
    if (pick === 1 || (pick === 0 && pressed & ~TAP)) unpause(now)
    else if (pick === 2) quit(now)
    pressed = 0
  } else if (mode === 'over') {
    if (!overReady && now - overAt > 1000) {
      overReady = true
      overDialog()
    }
    if (overReady && pressed) start(now)
    pressed = 0
  }
  if (mode === 'play') {
    if (pressed & START) pause()
    else play(now, down)
  }
  colors(now)
  if (mode === 'pause' || ((mode === 'title' || mode === 'over') && now - idleFrom > IDLE_MS)) frameos.setNextSleep(3600)
  return frameos.pixels(cells!, pal, opts)
}

export function onEvent(app, context) {
  const event = context.event
  if (event === 'close') {
    // Every finger lets go, and a game going on pauses.
    releaseAll()
    if (mode === 'play') press(START)
    return false
  }
  if (event === 'open') return mode !== 'slow'
  if (event === 'back') press(START)
  else if (event === 'forward') press(mode === 'play' ? 0 : 16)
  else if (handle(event, context.payload || {}, keys) < 0) return false
  idleFrom = Date.now()
  return mode !== 'play' && mode !== 'slow'
}

// --- settings and the layout ---------------------------------------------------------------

function settings(app: any, w: number, h: number, now: number, isRound: boolean) {
  settingsAt = now
  round = isRound
  const st = app.state
  const frame = app.frame
  const fresh = !cells
  if (fresh) {
    scores = readScores(st.highScores)
    setButtons('') // every GPIO key is the button
  }
  hc = highContrast(st.contrast, frame)
  fast = fastScreen(frame)
  difficulty = ['easy', 'normal', 'hard'].indexOf(choice(st.difficulty, ['normal', 'easy', 'hard']))
  gems = choice(st.gems, ['on', 'off']) === 'on'
  cave = ['amethyst', 'ember', 'frost'].indexOf(choice(st.cave, ['amethyst', 'ember', 'frost']))
  const colorsNow = cave + ':' + hc
  if (colorsNow !== colorKey) {
    colorKey = colorsNow
    gameColors(pal, cave, hc)
    uiColors(pal, theme(cave), hc)
  }
  const size = cellSize(st.pixelSize, w, h, 120)
  const key = [w, h, size, fast, round].join(':')
  if (key === layoutKey && !fresh) return
  layoutKey = key
  width = w
  height = h
  px = size
  cols = Math.max(40, Math.floor(w / px))
  rows = Math.max(40, Math.floor(h / px))
  cells = new Uint8Array(cols * rows)
  saved = null
  opts.width = cols
  opts.height = rows
  opts.pixelSize = px
  target(cells, cols, rows)
  if (!fast) {
    mode = 'slow'
    drawSlowCard(cols, rows, 'CAVE FLYER', ['A ONE-BUTTON GAME FOR', 'A FAST SCREEN: LCD OR HDMI.', '',
      'ON E-PAPER IT SLEEPS HERE.'], scores)
    return
  }
  // A strip for the score, tall enough for its pause button to take a finger.
  const strip = Math.max(7, Math.ceil(40 / px))
  setField(cells, cols, rows, strip, round ? Math.ceil(12 / px) : 0)
  setHitTest((x, y) => {
    const cx = x / px
    const cy = y / px
    return cx >= PAUSE_BOX[0] - 2 && cy < PAUSE_BOX[1] + PAUSE_BOX[3] + 2 ? START : 0
  })
  setBest(scores.length ? scores[0] : 0)
  if (fresh) {
    reseed(now)
    idleFrom = now
    const snap = frameos.recall('snap') as any
    if (snap && snap.distance) {
      resume(snap, difficulty, gems)
      mode = 'pause'
    } else mode = 'title'
  } else if (mode === 'play') {
    resume(snapshot(), difficulty, gems)
    mode = 'pause'
  }
  if (mode === 'slow') mode = 'title'
  if (mode === 'title') {
    stillCave(difficulty)
    titlePage = -1
  } else if (mode === 'over') newRun(difficulty, gems)
  drawHud(true)
  if (mode === 'pause') {
    frame(0, false)
    pauseDialog()
  } else if (mode === 'over') overDialog()
}

// --- the modes -------------------------------------------------------------------------------

function start(now: number) {
  newRun(difficulty, gems)
  mode = 'play'
  rank = -1
  clockReset(now)
  drawHud(true)
}

function play(now: number, down: boolean) {
  frame(stepsDue(now, STEP_MS, 4), down)
  drawHud(false)
  if (S.over) {
    mode = 'over'
    overAt = now
    overReady = false
    idleFrom = now
    rank = addScore(scores, S.score)
    setBest(scores.length ? scores[0] : 0)
    frameos.remember('snap', null)
    overDialog()
    return
  }
  if (now - snapAt > 1000) {
    snapAt = now
    frameos.remember('snap', snapshot())
  }
}

function pause() {
  mode = 'pause'
  releaseAll()
  frameos.remember('snap', snapshot())
  pauseDialog()
}

function unpause(now: number) {
  mode = 'play'
  if (saved) cells!.set(saved)
  clockReset(now)
}

function quit(now: number) {
  mode = 'title'
  idleFrom = now
  frameos.remember('snap', null)
  stillCave(difficulty)
  titlePage = -1
  S.distance = 0
  S.gems = 0
  drawHud(true)
}

function pauseDialog() {
  // Keep what the dialog covers, to put back on resume.
  if (!saved || saved.length !== cells!.length) saved = new Uint8Array(cells!.length)
  saved.set(cells!)
  clip(FIELD[0], FIELD[1], FIELD[2], FIELD[3])
  drawPause(FIELD[0], FIELD[1], FIELD[2], FIELD[3], 'P OR ANY KEY: RESUME')
}

function overDialog() {
  clip(FIELD[0], FIELD[1], FIELD[2], FIELD[3])
  const lines = gems ? ['DISTANCE ' + S.distance, 'GEMS ' + S.gems, 'SCORE ' + S.score] : ['DISTANCE ' + S.distance]
  drawGameOver(FIELD[0], FIELD[1], FIELD[2], FIELD[3], 'CRASHED', lines, rank, scores, overReady, 'TAP OR ANY KEY')
}

/** The title: a still cave, the flyer hovering, and a card beside it. */
function titleScreen(now: number) {
  hover(now)
  const page = scores.length ? (((now - idleFrom) / 6000) | 0) & 1 : 0
  if (page === titlePage) return
  titlePage = page
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  clip(fx, fy, fw, fh)
  // The card sits right of the flyer where there is room, else in the middle
  // (on a round panel, right of the flyer in the circle).
  const left = round ? Math.max(4, ((cols / 4) | 0) + 8 - fx) : fw >= 100 ? ((fw / 4) | 0) + 10 : 4
  const cw = fw - left - (round ? 1 : 4)
  const s = fitScale(20, cw - 4, 2)
  const big = Math.max(1, Math.min(fitScale(6, cw - 6, 4), Math.floor(fh / 4.5 / 12)))
  const ch = Math.min(fh - 8, 13 * big + 46 * s + 12)
  const cy = fy + ((fh - ch) >> 1)
  dialog(fx + left, cy, cw, ch)
  const cx = fx + left + (cw >> 1)
  let y = cy + 3
  title('CAVE', cx, y, big, UI_TITLE, UI_SHADOW)
  title('FLYER', cx, y + 6 * big, big, UI_TITLE, UI_SHADOW)
  y += 13 * big + 2
  if (page === 0) {
    textCenter('HOLD TO RISE', cx, y, s, UI_TEXT)
    textCenter('LET GO TO FALL', cx, y + 7 * s, s, UI_TEXT)
    if (gems) textCenter('CATCH THE GEMS', cx, y + 14 * s, s, UI_ACCENT)
  } else drawScores(scores.slice(0, 3), cx, y, s)
  textCenter('TAP OR ANY KEY', cx, cy + ch - 7 * s - 2, s, UI_BLINK)
}

function colors(now: number) {
  trailColors(pal, trailHead(), cave, hc)
  if (!hc) {
    pal[GLOW] = (now >> 7) & 1 ? 0xffd040 : 0xff9a3a
    // The score flashes the gem's color when one is caught.
    pal[HUD_TEXT] = takeSparkle() ? CAVES[cave][GEM] : CAVES[cave][HUD_TEXT]
  }
  blink(pal, now, hc ? 0xffffff : 0xf4f0ff, hc ? 0 : 0x8080a0)
}

sources.art.ts:
// Cave flyer's colors and sprites, in three caves: amethyst, ember and frost.
// The trail behind the flyer is a range of 32 palette entries, one per
// column scrolled: its fade is the palette's, so no trail cell is redrawn.
import { sprite } from './gfx'

export const AIR = 0
export const HUD = 2
export const HUD_TEXT = 3
export const HUD_DIM = 4
export const WALL = 8 // walls are 8..15: what the flyer crashes into
export const WALL2 = 9
export const WALL3 = 10
export const EDGE = 11
export const EDGE2 = 12
export const PILLAR = 13
export const PILLAR_EDGE = 14
export const WALL_LAST = 15
export const BODY = 16
export const WING = 17
export const EYE = 18
export const GLOW = 19
export const GEM = 20
export const GEM_HI = 21
export const GEM_DARK = 22
export const SPARK = 24
export const TRAIL = 32 // .. 63
export const TRAIL_N = 32

// air, -, hud, hud text, hud dim, -, -, -, wall, wall2, wall3, edge, edge2, pillar, pillar edge, -,
// body, wing, eye, glow, gem, gem hi, gem dark, -, spark
const AMETHYST = [0x0c0718, 0, 0x150c26, 0xf0e6ff, 0x9a86c0, 0, 0, 0, 0x3a1f5c, 0x55307e, 0x24123c, 0xb07ee8,
  0xe0b8ff, 0x8a4ab8, 0xe8c8ff, 0, 0xfff0a0, 0x7fe8ff, 0x101020, 0xffd040, 0x4ef0b0, 0xe8fff4, 0x1a8a68, 0, 0xffffff]
const EMBER = [0x140806, 0, 0x1e0c08, 0xfff0e0, 0xc09080, 0, 0, 0, 0x4a1a12, 0x6a2618, 0x2a0e0a, 0xff7a2a,
  0xffd04a, 0x9a3a1a, 0xffb060, 0, 0xe8f4ff, 0x9ad8ff, 0x101020, 0x7ae8ff, 0x7aa8ff, 0xf0f6ff, 0x2a4ac8, 0, 0xffe0a0]
const FROST = [0x061420, 0, 0x0a1c2c, 0xeaf6ff, 0x86a8c4, 0, 0, 0, 0x2a5a7e, 0x3c7aa0, 0x183a56, 0xc8f0ff,
  0xffffff, 0x5a9ac0, 0xe8faff, 0, 0xffd27a, 0xff8a5a, 0x201010, 0xffb03a, 0xff6a9a, 0xfff0f6, 0xa02a5a, 0, 0xffffff]
export const CAVES = [AMETHYST, EMBER, FROST]
// The trail's colors, newest first, per cave.
const TRAILS = [[0xfff0a0, 0xffd040, 0xd08aff], [0xe8f4ff, 0x7ae8ff, 0xff7a2a], [0xffd27a, 0xffb03a, 0xc8f0ff]]
// In black and white: 1 white.
const INK = '0001100000011010110110101000'

export const THEMES = [
  { title: [0xfff0ff, 0xe8c0ff, 0xc890ff, 0xa060f0, 0x7a3ad0], accent: 0x7fe8ff, panel: 0x150c26, face: 0x2a1a44, lit: 0xd08aff },
  { title: [0xfff6c0, 0xffd860, 0xffa03a, 0xff6a2a, 0xd8302a], accent: 0xffb03a, panel: 0x1e0c08, face: 0x3a1a12, lit: 0xff9a4a },
  { title: [0xffffff, 0xd8f4ff, 0xa8e0ff, 0x70c0f0, 0x3a90d0], accent: 0xffd27a, panel: 0x0a1c2c, face: 0x1a3a56, lit: 0x8ad8ff },
]

/** The kit's theme for a cave. */
export function theme(cave: number) {
  const t = THEMES[cave]
  return {
    title: t.title, shadow: 0x05030a, panel: t.panel, edge: 0x6a6a90, border: 0x8a8ab0, face: t.face, lit: t.lit,
    icon: 0xf0f0ff, iconLit: 0x101018, text: 0xf4f0ff, dim: 0xa0a0c0, dialog: t.panel, dialogEdge: 0xa0a0d0,
    accent: t.accent, good: 0xffe14a,
  }
}

/** The game's part of the palette. */
export function gameColors(pal: Uint32Array, cave: number, hc: boolean) {
  const c = CAVES[cave]
  for (let i = 0; i < 32; i++) {
    const v = i < c.length ? c[i] : 0
    pal[i] = hc ? (i < INK.length && INK[i] === '1' ? 0xffffff : 0) : v
  }
}

/** The trail's fade for this moment: `head` is the entry drawn last. */
export function trailColors(pal: Uint32Array, head: number, cave: number, hc: boolean) {
  const t = TRAILS[cave]
  const air = hc ? 0 : CAVES[cave][AIR]
  for (let j = 0; j < TRAIL_N; j++) {
    const age = (head - j + TRAIL_N) % TRAIL_N
    let color = air
    if (hc) color = age < 10 && age % 3 !== 2 ? 0xffffff : 0
    else if (age < 4) color = t[0]
    else if (age < 9) color = t[1]
    else if (age < 16) color = mix(t[2], air, (age - 9) / 7)
    pal[TRAIL + j] = color
  }
}

function mix(a: number, b: number, t: number): number {
  const r = ((a >> 16) & 255) + ((((b >> 16) & 255) - ((a >> 16) & 255)) * t)
  const g = ((a >> 8) & 255) + ((((b >> 8) & 255) - ((a >> 8) & 255)) * t)
  const bl = (a & 255) + (((b & 255) - (a & 255)) * t)
  return ((r | 0) << 16) | ((g | 0) << 8) | (bl | 0)
}

// The Lumen, a little glowing flyer, wings up and wings down.
export const FLY_UP = sprite('..ww...|...ww..|gbbbbbe|.bbbbb.|.......', 'wgbe', [WING, GLOW, BODY, EYE])
export const FLY_DOWN = sprite('.......|.bbbbb.|gbbbbbe|...ww..|..ww...', 'wgbe', [WING, GLOW, BODY, EYE])

sources.game.ts:
// Cave flyer's game: an endless cave scrolling left a column at a time. A
// scroll is one native copyWithin of the field's cells and one new column
// on the right, so a frame costs a column or two of cells, not a screen. The
// flyer stays at a quarter of the width: holding the button lifts it,
// letting go lets it fall. Walls, pillars and gems are palette indexes in
// the cells, so a crash or a catch is read straight off the cells it covers.
import { blit, clip, fill, number, text, textWidth } from './gfx'
import { rfloat, rint } from './ui'
import {
  AIR, EDGE, EDGE2, FLY_DOWN, FLY_UP, GEM, GEM_DARK, GEM_HI, HUD, HUD_DIM, HUD_TEXT, PILLAR, PILLAR_EDGE, SPARK, TRAIL,
  TRAIL_N, WALL, WALL2, WALL3, WALL_LAST,
} from './art'

let cells: Uint8Array = new Uint8Array(1)
let cols = 1
let FY = 0 // the field: every row from FY down, the whole width
let FH = 1
let HH = 7 // the score strip
let flyX = 0
// A round panel (only the circle inside the square shows): the strip's text and
// pause button where the circle is wide enough for them, and a band under the
// field as deep as the circle hides below the flyer.
let hudLeft = 0
let hudTy = 0
let bandRows = 0
export const FIELD = new Int16Array(4)
/** The pause button in the strip: x, y, w, h. */
export const PAUSE_BOX = new Int16Array(4)

export function setField(c: Uint8Array, gridCols: number, gridRows: number, stripRows: number, roundEdge = 0) {
  cells = c
  cols = gridCols
  HH = stripRows
  FY = HH
  FH = gridRows - HH
  flyX = (cols / 4) | 0
  FIELD[0] = 0
  FIELD[1] = FY
  FIELD[2] = cols
  FIELD[3] = FH
  const size = Math.max(6, HH - 2)
  PAUSE_BOX[0] = cols - size - 1
  PAUSE_BOX[1] = 1
  PAUSE_BOX[2] = size
  PAUSE_BOX[3] = size
  hudLeft = 0
  hudTy = (HH - 5) >> 1
  bandRows = 0
  if (roundEdge > 0) roundField(gridRows, stripRows, size, roundEdge)
}

function roundField(gridRows: number, stripRows: number, size: number, edge: number) {
  const cx = cols / 2
  const cy = gridRows / 2
  const inner = Math.min(cols, gridRows) / 2 - edge
  const half = (d: number) => Math.sqrt(Math.max(0, inner * inner - d * d))
  // The distance, the gems and the pause button (the best does not fit), centred.
  const wide = 50 + size
  const top = Math.max(0, Math.floor(cy - half(wide / 2)))
  HH = top + stripRows
  FY = HH
  hudLeft = Math.round(cx - wide / 2)
  hudTy = top + ((stripRows - 5) >> 1)
  PAUSE_BOX[0] = hudLeft + wide - size
  PAUSE_BOX[1] = top + 1
  bandRows = Math.max(0, gridRows - Math.floor(cy + half(cx - flyX)))
  FH = gridRows - HH - bandRows
  // Dialogs: in the middle three quarters of the field, as wide as the circle there.
  const dy = Math.round(FH * 0.12)
  const hw = Math.floor(half(Math.max(Math.abs(FY + dy - cy), Math.abs(FY + FH - dy - cy))))
  FIELD[0] = Math.round(cx - hw)
  FIELD[1] = FY + dy
  FIELD[2] = 2 * hw
  FIELD[3] = FH - 2 * dy
}

// --- the cave's shape ---------------------------------------------------------------

let worldX = 0 // columns made so far
let ceil = 0 // rows of rock from the top and from the bottom
let floor = 0
let ceilTo = 0
let floorTo = 0
let retarget = 0
let obstacle = 0 // columns of the pillar being made, and its rows
let obsTop = 0
let obsWidth = 0
let obsKind = 0
let obsLen = 0
let obsMid = 0
let obsBottom = 0
let nextObstacle = 0
let nextGem = 0
let gemCol = -1 // the gem being made: its column (0..4) and middle row
let gemRow = 0
const NG = 8
const gemX = new Int16Array(NG).fill(-99) // gems in the field: their middle column and row
const gemY = new Int16Array(NG)
let difficulty = 1
let pickups = true
// A table of noise for the rock's speckles: two lookups a cell, no call.
const NOISE = new Uint8Array(256)
for (let i = 0; i < 256; i++) NOISE[i] = (i * 167 + 13) % 251 ^ ((i * 7) & 255)

function minGap(): number {
  const tight = [0.36, 0.3, 0.25][difficulty]
  const g = 0.56 - worldX / [9000, 6500, 4500][difficulty]
  return Math.max(16, (FH * (g > tight ? g : tight)) | 0)
}

/** A new cave from an open start. */
function freshCave() {
  worldX = 0
  ceil = floor = (FH * 0.12) | 0
  ceilTo = floorTo = ceil
  retarget = cols + 30 // the first screen and a bit: open, flat walls
  obstacle = 0
  nextObstacle = 160
  nextGem = 60
  gemCol = -1
  gemX.fill(-99)
  cells.fill(AIR, FY * cols, (FY + FH) * cols)
  for (let x = 0; x < cols; x++) column(x)
}

/** The cave's next column, at x. */
function column(x: number) {
  worldX++
  // Ceiling and floor drift towards heights picked every so often, never
  // closer than the gap allowed now.
  if (--retarget <= 0) {
    retarget = 14 + rint(30)
    const gap = minGap()
    const room = FH - gap - 4
    // The rock the gap leaves, shared out between ceiling and floor.
    const top = rint(room > 2 ? room : 2)
    ceilTo = 2 + top
    floorTo = 2 + (room - top) * (0.4 + rfloat() * 0.6)
  }
  ceil += (ceilTo - ceil) * 0.09
  floor += (floorTo - floor) * 0.09
  const gap = minGap()
  if (FH - ceil - floor < gap) {
    const over = gap - (FH - ceil - floor)
    ceil -= over / 2
    floor -= over / 2
  }
  // A little roughness on top of the drift: rock, not a curve.
  const rough = (worldX * 37) % 7
  const c = (ceil < 1 ? 1 : ceil | 0) + (rough === 0 ? 1 : rough === 3 ? -1 : 0)
  const f = FH - (floor < 1 ? 1 : floor | 0) + (rough === 5 ? -1 : rough === 1 ? 1 : 0)
  // A pillar now and then, with a way past it above or below.
  if (obstacle === 0 && --nextObstacle <= 0 && worldX > 120) {
    nextObstacle = [140, 100, 70][difficulty] + rint(80)
    obstacle = obsWidth = 5 + rint(4)
    const g = f - c
    obsKind = rint(3)
    obsLen = (g * (0.32 + rfloat() * 0.18)) | 0
    obsMid = c + ((g * (0.3 + rfloat() * 0.4)) | 0)
  }
  if (obstacle > 0) {
    // A crystal: longest in its middle columns, tapering to its sides.
    const k = obsWidth - obstacle
    const side = k < obsWidth - 1 - k ? k : obsWidth - 1 - k
    const len = (obsLen * (side === 0 ? 0.55 : side === 1 ? 0.85 : 1)) | 0
    if (obsKind === 0) {
      obsTop = c
      obsBottom = c + len
    } else if (obsKind === 1) {
      obsTop = f - len
      obsBottom = f
    } else {
      obsTop = obsMid - (len >> 2)
      obsBottom = obsMid + (len >> 2)
    }
  }
  // A gem in the open now and then.
  if (pickups && gemCol < 0 && --nextGem <= 0 && obstacle === 0) {
    nextGem = 40 + rint(60)
    gemCol = 0
    gemRow = c + 4 + rint(Math.max(1, f - c - 8))
    for (let g = 0; g < NG; g++) if (gemX[g] < -10) {
      gemX[g] = x + 2
      gemY[g] = gemRow
      break
    }
  }
  const pillar = obstacle > 0
  const pillarEdge = obstacle === 1 || obstacle === obsWidth
  let at = FY * cols + x
  for (let y = 0; y < FH; y++, at += cols) {
    let v = AIR
    if (y < c || y >= f) {
      const depth = y < c ? c - 1 - y : y - f
      const h = NOISE[(worldX + NOISE[y & 255]) & 255] % 11
      v = depth === 0 ? EDGE2 : depth < 2 ? EDGE : depth > 6 ? (h === 0 ? WALL2 : WALL3) : h < 2 ? WALL2 : WALL
    } else if (pillar && y >= obsTop && y < obsBottom) {
      v = pillarEdge || y === obsTop || y === obsBottom - 1 ? PILLAR_EDGE : PILLAR
    } else if (gemCol >= 0) {
      const half = 2 - (gemCol > 2 ? gemCol - 2 : 2 - gemCol)
      const dy = y - gemRow
      if (dy >= -half && dy <= half) v = gemCol === 2 && dy === 0 ? GEM_HI : dy === -half || dy === half ? GEM_DARK : GEM
    }
    cells[at] = v
  }
  if (obstacle > 0) obstacle--
  if (gemCol >= 0 && ++gemCol > 4) gemCol = -1
}

// --- the flyer and the run ------------------------------------------------------------------

export const S = { score: 0, distance: 0, gems: 0, over: false }
let y = 0 // the flyer's top row, in the field
let vy = 0
let scrolled = 0 // columns scrolled: the trail's clock
let owed = 0 // a fraction of a column
let speed = 0 // columns a second
let dying = 0
let flap = 0
const trailY = new Int16Array(TRAIL_N).fill(-1)
// What the flyer covers, put back before it moves.
const under = new Uint8Array(64)
let drawnX = -1
let drawnY = -1
let drawnSprite: any = FLY_UP

export function newRun(diff: number, gems: boolean) {
  difficulty = diff
  pickups = gems
  S.score = 0
  S.distance = 0
  S.gems = 0
  S.over = false
  dying = 0
  vy = 0
  speed = [30, 38, 46][diff]
  owed = 0
  trailY.fill(-1)
  drawnX = -1
  freshCave()
  y = (FH / 2 - 2) | 0
}

/** The title's cave: a still one with the flyer hovering in it. */
export function stillCave(diff: number) {
  difficulty = diff
  pickups = true
  freshCave()
  drawnX = -1
  y = (FH / 2 - 2) | 0
}

/** Takes the flyer away, runs `steps` steps with the button `down` or not, draws it again. */
export function frame(steps: number, down: boolean) {
  erase()
  for (let i = 0; i < steps && !S.over; i++) tick(down)
  if (!dying) draw(vy < 0.05 && (flap++ >> 2) & 1 ? FLY_DOWN : FLY_UP)
}

/** The title's flyer, bobbing up and down. */
export function hover(now: number) {
  erase()
  const target = (FH / 2 - 2 + Math.sin(now / 400) * FH * 0.08) | 0
  y = target
  draw((now >> 7) & 1 ? FLY_UP : FLY_DOWN)
}

function erase() {
  if (drawnX < 0) return
  const s = drawnSprite
  let k = 0
  for (let sy = 0; sy < s.h; sy++) {
    const row = (FY + drawnY + sy) * cols + drawnX
    for (let sx = 0; sx < s.w; sx++) cells[row + sx] = under[k++]
  }
  drawnX = -1
}

function draw(s: any) {
  const yy = y < 0 ? 0 : y > FH - s.h ? FH - s.h : y | 0
  let k = 0
  for (let sy = 0; sy < s.h; sy++) {
    const row = (FY + yy + sy) * cols + flyX
    for (let sx = 0; sx < s.w; sx++) under[k++] = cells[row + sx]
  }
  clip(0, FY, cols, FH)
  blit(s, flyX, FY + yy)
  drawnX = flyX
  drawnY = yy
  drawnSprite = s
}

function tick(down: boolean) {
  if (dying) {
    // Sparks fall away where it crashed; then the run is over.
    if (dying < 40 && dying % 3 === 0) spark()
    if (++dying > 70) S.over = true
    return
  }
  vy += down ? -0.1 : 0.085
  if (vy < -1.2) vy = -1.2
  if (vy > 1.5) vy = 1.5
  y += vy
  // Faster the further it goes: half as fast again by 3000.
  const rate = speed * (1 + Math.min(1.2, S.distance / 6000))
  owed += rate / 60
  while (owed >= 1) {
    owed -= 1
    scroll()
  }
  if (y < 0 || y > FH - 5) {
    crash()
    return
  }
  // What the flyer's cells would cover: rock is the end, a gem is caught.
  const s = vy < 0.05 ? FLY_DOWN : FLY_UP
  const yy = y | 0
  for (let sy = 0; sy < s.h; sy++) {
    const row = (FY + yy + sy) * cols + flyX
    for (let sx = 0; sx < s.w; sx++) {
      if (s.d[sy * s.w + sx] === 255) continue
      const v = cells[row + sx]
      if (v >= WALL && v <= WALL_LAST) {
        crash()
        return
      }
      if (v >= GEM && v <= GEM_DARK) catchGem(flyX + sx, yy + sy)
    }
  }
}

function scroll() {
  // Everything in the field one column left, and a new column on the right.
  const start = FY * cols
  cells.copyWithin(start, start + 1, (FY + FH) * cols)
  column(cols - 1)
  for (let g = 0; g < NG; g++) if (gemX[g] > -50) gemX[g]--
  S.distance++
  S.score++
  // The trail: one cell behind the flyer each column. Its entry 32 columns
  // ago is taken off the screen first, so it never lights up again.
  scrolled++
  const k = scrolled % TRAIL_N
  const oldY = trailY[k]
  const oldX = flyX - 1 - TRAIL_N
  if (oldY >= 0 && oldX >= 0) {
    const at = (FY + oldY) * cols + oldX
    if (cells[at] === TRAIL + k) cells[at] = AIR
  }
  const ty = ((y | 0) + 2) | 0
  if (ty >= 0 && ty < FH) {
    const at = (FY + ty) * cols + flyX - 1
    if (cells[at] === AIR) {
      cells[at] = TRAIL + k
      trailY[k] = ty
    } else trailY[k] = -1
  }
}

/** The trail's newest entry, for its palette. */
export function trailHead(): number {
  return scrolled % TRAIL_N
}

function catchGem(cx: number, cy: number) {
  for (let g = 0; g < NG; g++) {
    const gx = gemX[g]
    if (gx < -10 || cx < gx - 3 || cx > gx + 3 || cy < gemY[g] - 3 || cy > gemY[g] + 3) continue
    // Off the screen with it: its cells back to air.
    for (let dy = -2; dy <= 2; dy++) {
      for (let dx = -2; dx <= 2; dx++) {
        const x = gx + dx
        const yy = gemY[g] + dy
        if (x < 0 || x >= cols || yy < 0 || yy >= FH) continue
        const at = (FY + yy) * cols + x
        if (cells[at] >= GEM && cells[at] <= GEM_DARK) cells[at] = AIR
      }
    }
    gemX[g] = -99
    S.gems++
    S.score += 50
    sparkle = 12
    return
  }
}
let sparkle = 0
export function takeSparkle(): number {
  if (sparkle > 0) sparkle--
  return sparkle
}

function crash() {
  dying = 1
  drawnX = -1
  // The flyer breaks up where it was.
  const yy = y < 0 ? 0 : y > FH - 5 ? FH - 5 : y | 0
  fill(flyX, FY + yy, 7, 5, AIR)
  for (let k = 0; k < 10; k++) {
    const x = flyX + rint(9) - 1
    const r = yy + rint(7) - 1
    if (r >= 0 && r < FH && x >= 0) cells[(FY + r) * cols + x] = SPARK
  }
}

function spark() {
  const x = flyX + rint(12) - 3
  const r = ((y | 0) + rint(10) - 3) | 0
  if (r >= 0 && r < FH && x >= 0 && x < cols && cells[(FY + r) * cols + x] === AIR) cells[(FY + r) * cols + x] = SPARK
}

// --- the strip ------------------------------------------------------------------------------

let shownScore = -1
let shownGems = -1
let best = 0

export function setBest(n: number) {
  best = n
}

/** Distance, gems, best and the pause button, drawn again when they change. */
export function drawHud(force: boolean) {
  if (!force && shownScore === S.score && shownGems === S.gems) return
  shownScore = S.score
  shownGems = S.gems
  if (force && bandRows) {
    clip(0, FY + FH, cols, bandRows)
    fill(0, FY + FH, cols, bandRows, HUD)
  }
  clip(0, 0, cols, HH)
  fill(0, 0, cols, HH, HUD)
  const ty = hudTy
  const w = number(S.distance, 2 + hudLeft, ty, 1, HUD_TEXT, 4)
  text('M', 3 + hudLeft + w, ty, 1, HUD_DIM)
  let x = 3 + hudLeft + w + 8
  if (pickups) {
    // A small gem and how many.
    fill(x + 1, ty, 1, 5, GEM)
    fill(x, ty + 1, 3, 3, GEM)
    fill(x + 1, ty + 2, 1, 1, GEM_HI)
    x += 5
    x += number(S.gems, x, ty, 1, HUD_TEXT) + 6
  }
  const bx = PAUSE_BOX[0]
  if (x + textWidth('BEST 0000', 1) < bx - 2) {
    text('BEST', x, ty, 1, HUD_DIM)
    number(best, x + 18, ty, 1, HUD_TEXT, 4)
  }
  // The pause button: two bars in a box.
  const by = PAUSE_BOX[1]
  const bs = PAUSE_BOX[2]
  fill(bx, by, bs, bs, HUD_DIM)
  fill(bx + 1, by + 1, bs - 2, bs - 2, HUD)
  const bar = Math.max(1, (bs / 6) | 0)
  fill(bx + (bs >> 1) - bar - 1, by + 2, bar, bs - 4, HUD_TEXT)
  fill(bx + (bs >> 1) + 1, by + 2, bar, bs - 4, HUD_TEXT)
  clip(0, FY, cols, FH)
}

/** The run's place, to come back to after the interpreter was dropped. */
export function snapshot() {
  return { score: S.score, distance: S.distance, gems: S.gems }
}

export function resume(snap: any, diff: number, gems: boolean) {
  newRun(diff, gems)
  S.score = snap.score | 0
  S.distance = snap.distance | 0
  S.gems = snap.gems | 0
  worldX = S.distance
}

sources.gfx.ts:
// Drawing into the cells of the 8-bit palette mode: a byte a cell, an index
// into the game's palette. Everything here draws into one target, set with
// target() when the cells are made; every shape is clipped to it. Rows are
// filled with Uint8Array.fill, which is one native memset a run: far cheaper
// than a loop of cell writes in QuickJS.

let C: Uint8Array = new Uint8Array(1)
let CW = 1 // the grid's width: a row's stride
// The clip box: nothing is drawn outside [X0, X1) x [Y0, Y1).
let X0 = 0
let Y0 = 0
let X1 = 1
let Y1 = 1

/** The cells everything draws into: a grid `w` cells wide and `h` high,
 *  clipped to all of it. */
export function target(cells: Uint8Array, w: number, h: number) {
  C = cells
  CW = w
  X0 = 0
  Y0 = 0
  X1 = w
  Y1 = h
}

/** Draw only inside this rectangle (a play area under a score strip). */
export function clip(x: number, y: number, w: number, h: number) {
  X0 = x
  Y0 = y
  X1 = x + w
  Y1 = y + h
}

/** A filled rectangle. */
export function fill(x: number, y: number, w: number, h: number, v: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  if (x0 >= x1) return
  for (let r = y0; r < y1; r++) C.fill(v, r * CW + x0, r * CW + x1)
}

/** One cell. */
export function put(x: number, y: number, v: number) {
  if (x >= X0 && y >= Y0 && x < X1 && y < Y1) C[(y | 0) * CW + (x | 0)] = v
}

/** A button-ish box: a face with a border and its corners cut off (left as
 *  `under`, what the box sits on). */
export function box(x: number, y: number, w: number, h: number, face: number, border: number, under: number) {
  fill(x, y, w, h, border)
  fill(x + 1, y + 1, w - 2, h - 2, face)
  put(x, y, under)
  put(x + w - 1, y, under)
  put(x, y + h - 1, under)
  put(x + w - 1, y + h - 1, under)
}

/** Copies a rectangle from `layer` (cells of the same grid) back into the
 *  target: what a moving thing covered, put back. */
export function restore(layer: Uint8Array, x: number, y: number, w: number, h: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  for (let r = y0; r < y1; r++) {
    const row = r * CW
    for (let i = row + x0; i < row + x1; i++) C[i] = layer[i]
  }
}

// --- sprites ---------------------------------------------------------------

/** A sprite: `w` x `h` palette indexes, 255 where it is see-through. */
export type Sprite = { w: number; h: number; d: Uint8Array }

/**
 * A sprite from a compact string: rows split by `|`, a character a cell, `.`
 * see-through, and every other character the palette index at its place in
 * `values` for its place in `keys` ("ab", [12, 13]: a is 12, b is 13).
 */
export function sprite(text: string, keys: string, values: number[]): Sprite {
  const lines = text.split('|')
  const h = lines.length
  let w = 0
  for (const line of lines) if (line.length > w) w = line.length
  const d = new Uint8Array(w * h).fill(255)
  for (let y = 0; y < h; y++) {
    const line = lines[y]
    for (let x = 0; x < line.length; x++) {
      const k = keys.indexOf(line[x])
      if (k >= 0) d[y * w + x] = values[k]
    }
  }
  return { w, h, d }
}

/** Draws a sprite with its top left at (x, y). `tint` (when not 255) paints
 *  every solid cell that one index: a flash when something is hit. */
export function blit(s: Sprite, x: number, y: number, tint = 255) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      const v = d[src + sx]
      if (v !== 255) C[dst + sx] = tint === 255 ? v : tint
    }
  }
}

/** Puts back what a sprite at (x, y) covered: only its solid cells, from `layer`. */
export function unblit(s: Sprite, x: number, y: number, layer: Uint8Array) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      if (d[src + sx] !== 255) C[dst + sx] = layer[dst + sx]
    }
  }
}

// --- text ------------------------------------------------------------------

// A 3x5 font, 15 bits a glyph, the top row first and each row's left dot its
// high bit. Letters, digits and a little punctuation; `@` is a heart.
const GLYPHS: Record<string, number> = {
  A: 0x2bed, B: 0x6bae, C: 0x3923, D: 0x6b6e, E: 0x79a7, F: 0x79a4, G: 0x396b, H: 0x5bed, I: 0x7497,
  J: 0x126a, K: 0x5bad, L: 0x4927, M: 0x5fed, N: 0x6b6d, O: 0x2b6a, P: 0x6ba4, Q: 0x2b73, R: 0x6bad,
  S: 0x388e, T: 0x7492, U: 0x5b6f, V: 0x5b6a, W: 0x5bfd, X: 0x5aad, Y: 0x5a92, Z: 0x72a7,
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, '+': 0x05d0, '<': 0x1511, '>': 0x4454, '.': 0x0002, ':': 0x0410, '/': 0x12a4, ' ': 0,
  '!': 0x2482, '?': 0x7282, "'": 0x2400, ',': 0x0014, '%': 0x52a5, '#': 0x5f7d, '*': 0x0aa8, '=': 0x0e38,
  '(': 0x2922, ')': 0x224a, '@': 0x5fd0, '_': 0x0007,
}

/** A character's 15 dots (0 for one the font lacks). */
export function glyphBits(ch: string): number {
  return GLYPHS[ch] ?? GLYPHS[ch.toUpperCase()] ?? 0
}

/** Cells a line of text takes at `scale`: 4 dots a letter, less the last gap. */
export function textWidth(text: string, scale: number): number {
  return text.length ? (text.length * 4 - 1) * scale : 0
}

/**
 * Text with its top left at (x, y), `scale` cells a dot. With `ramp` each row
 * of dots is one index further from `v` (v, v+1, ... v+4: a gradient down the
 * letters); with `upside` it is turned 180 degrees, for the player across the
 * table.
 */
export function text(s: string, x: number, y: number, scale: number, v: number, ramp = false, upside = false) {
  const n = s.length
  for (let g = 0; g < n; g++) {
    const ch = s[upside ? n - 1 - g : g]
    const bits = glyphBits(ch)
    if (!bits) continue
    const left = x + g * 4 * scale
    for (let i = 0; i < 15; i++) {
      const bit = upside ? i : 14 - i
      if (!(bits & (1 << bit))) continue
      const dotRow = (i / 3) | 0
      fill(left + (i % 3) * scale, y + dotRow * scale, scale, scale, ramp ? v + (upside ? 4 - dotRow : dotRow) : v)
    }
  }
}

/** Text centred on column `cx`. */
export function textCenter(s: string, cx: number, y: number, scale: number, v: number, ramp = false) {
  text(s, cx - ((textWidth(s, scale) / 2) | 0), y, scale, v, ramp)
}

/** A headline: gradient letters (`v` .. `v`+4) over a drop shadow `shadow`. */
export function title(s: string, cx: number, y: number, scale: number, v: number, shadow: number) {
  const x = cx - ((textWidth(s, scale) / 2) | 0)
  const off = scale > 1 ? (scale / 2) | 0 : 1
  text(s, x + off, y + off, scale, shadow)
  text(s, x, y, scale, v, true)
}

// The digits' glyphs, for numbers drawn every frame without making a string.
const DIGITS = new Int32Array(10)
for (let d = 0; d < 10; d++) DIGITS[d] = GLYPHS[String(d)]

/** A whole number at (x, y), at least `width` digits (zeros in front), with
 *  no string made: a speed or a clock drawn every frame. Answers its width. */
export function number(n: number, x: number, y: number, scale: number, v: number, width = 1): number {
  n = n < 0 ? 0 : n | 0
  let count = 1
  for (let k = n; k >= 10; k = (k / 10) | 0) count++
  if (count < width) count = width
  let at = x + (count - 1) * 4 * scale
  for (let i = 0; i < count; i++) {
    const bits = DIGITS[n % 10]
    for (let b = 0; b < 15; b++) {
      if (bits & (1 << (14 - b))) fill(at + (b % 3) * scale, y + ((b / 3) | 0) * scale, scale, scale, v)
    }
    n = (n / 10) | 0
    at -= 4 * scale
  }
  return count * 4 * scale - scale
}

sources.input.ts:
// Input for the games: touch (each finger by its pointerId, so one can hold
// left while another fires), GPIO buttons (down and up the moment they
// happen) and a keyboard, all folded into one set of action bits. What is
// held is held(); a press that came and went between two frames still counts
// once through take(), so a quick tap of a GPIO key is never lost.

export const LEFT = 1
export const RIGHT = 2
export const UP = 4
export const DOWN = 8
export const A = 16
export const B = 32
export const START = 64 // pause / resume / start
export const TAP = 128 // a finger or a click on the play area (not a control)

const ACTIONS: Record<string, number> = {
  left: LEFT, right: RIGHT, up: UP, down: DOWN, a: A, fire: A, b: B, bomb: B, brake: B,
  start: START, pause: START, gas: A, jump: A, button: A,
}

const MAX = 32 // pointer ids are folded into this many slots
const ptrBits = new Uint8Array(MAX)
const ptrDrag = new Uint8Array(MAX)
/** Which pointers are down on the play area (not on a control), by id. */
export const drags = ptrDrag
/** Where each dragging pointer is now and where it went down, in scene pixels. */
export const ptrX = new Int16Array(MAX)
export const ptrY = new Int16Array(MAX)
export const ptrStartX = new Int16Array(MAX)
export const ptrStartY = new Int16Array(MAX)
const pinBits = new Uint8Array(64)
let keyBits = 0
let gpioBits = 0
let latched = 0
let gpioSeen = false
let labels: Record<string, number> = {}
let hitTest: (x: number, y: number) => number = () => 0
// What was used last: 'touch', 'key' or 'gpio'.
let lastKind = ''
let tapX = 0
let tapY = 0

/** How a pointer at (x, y) scene pixels hits the on-screen controls: their
 *  action bits, or 0 for the play area (a drag there). */
export function setHitTest(fn: (x: number, y: number) => number) {
  hitTest = fn
}

/** The "Buttons" setting: `LEFT=left, RIGHT=right, KEY1=a`. Labels (and
 *  roles) are matched without case; a key it does not name is A. */
export function setButtons(spec: string) {
  labels = {}
  for (const part of String(spec || '').split(',')) {
    const eq = part.indexOf('=')
    if (eq < 0) continue
    const name = part.slice(0, eq).trim().toLowerCase()
    const action = ACTIONS[part.slice(eq + 1).trim().toLowerCase()]
    if (name && action) labels[name] = action
  }
}

function gpioAction(payload: any): number {
  const label = String(payload.label || '').toLowerCase()
  const role = String(payload.role || '').toLowerCase()
  return labels[label] || labels[role] || ACTIONS[label] || A
}

/** The default keys: arrows and WASD, Space / Z / J for A, X / K / C for B,
 *  Enter, P and Escape to pause. */
export function keyAction(code: string): number {
  switch (code) {
    case 'ArrowLeft': case 'KeyA': return LEFT
    case 'ArrowRight': case 'KeyD': return RIGHT
    case 'ArrowUp': case 'KeyW': return UP
    case 'ArrowDown': case 'KeyS': return DOWN
    case 'Space': case 'KeyZ': case 'KeyJ': return A
    case 'KeyX': case 'KeyK': case 'KeyC': return B
    case 'Enter': case 'NumpadEnter': case 'KeyP': case 'Escape': return START
  }
  return 0
}

function recount() {
  let g = 0
  for (let i = 0; i < 64; i++) g |= pinBits[i]
  gpioBits = g
}

/**
 * One input event. Answers the action bits it pressed (0 when it pressed
 * nothing, -1 when it was not input at all), so a game can react at once.
 * `keys` maps a key code to bits (keyAction by default).
 */
export function handle(event: string, p: any, keys: (code: string) => number = keyAction): number {
  if (event === 'pointerDown' || event === 'pointerMove') {
    const id = (p.pointerId | 0) & (MAX - 1)
    const x = p.x | 0
    const y = p.y | 0
    if (event === 'pointerMove' && !ptrBits[id] && !ptrDrag[id]) return 0 // a mouse passing over
    lastKind = 'touch'
    if (event === 'pointerDown') {
      const bits = hitTest(x, y)
      ptrBits[id] = bits
      ptrDrag[id] = bits ? 0 : 1
      ptrX[id] = ptrStartX[id] = x
      ptrY[id] = ptrStartY[id] = y
      tapX = x
      tapY = y
      latched |= bits || TAP
      return bits || TAP
    }
    ptrX[id] = x
    ptrY[id] = y
    if (ptrBits[id]) {
      // A thumb sliding from one button to the next presses that one.
      const bits = hitTest(x, y)
      const fresh = bits & ~ptrBits[id]
      ptrBits[id] = bits
      latched |= fresh
      return fresh
    }
    return 0
  }
  if (event === 'pointerUp' || event === 'pointerCancel') {
    const id = (p.pointerId | 0) & (MAX - 1)
    ptrBits[id] = 0
    ptrDrag[id] = 0
    return 0
  }
  if (event === 'keyDown' || event === 'keyUp') {
    const bits = keys(String(p.code || p.key || ''))
    if (!bits) return 0
    lastKind = 'key'
    if (event === 'keyUp') {
      keyBits &= ~bits
      return 0
    }
    if (p.repeat) return 0
    keyBits |= bits
    latched |= bits
    return bits
  }
  if (event === 'gpio') {
    gpioSeen = true
    lastKind = 'gpio'
    const pin = (p.pin | 0) & 63
    if (p.action === 'down') {
      const bits = gpioAction(p)
      pinBits[pin] = bits
      latched |= bits
      recount()
      return bits
    }
    if (p.action === 'up') {
      pinBits[pin] = 0
      recount()
    }
    return 0
  }
  if (event === 'button') {
    // Only where no gpio edges arrive: a press after the release.
    if (gpioSeen || (p.action !== 'press' && p.action !== 'doublePress')) return 0
    lastKind = 'gpio'
    const bits = gpioAction(p)
    latched |= bits
    return bits
  }
  return -1
}

/** Everything held now. */
export function held(): number {
  let bits = keyBits | gpioBits
  for (let i = 0; i < MAX; i++) bits |= ptrBits[i]
  return bits
}

/** Counts as a press of `bits` (a swipe in from an edge that means pause). */
export function press(bits: number) {
  latched |= bits
}

/** The presses since the last call. */
export function take(): number {
  const bits = latched
  latched = 0
  return bits
}

/** The id of a finger dragging on the play area, or -1. */
export function dragging(): number {
  for (let i = 0; i < MAX; i++) if (ptrDrag[i]) return i
  return -1
}

/** Where the last finger or click went down, in scene pixels. */
export function lastTapX(): number {
  return tapX
}
export function lastTapY(): number {
  return tapY
}

/** Every finger lets go (a pause, the scene closing). */
export function releaseAll() {
  ptrBits.fill(0)
  ptrDrag.fill(0)
  pinBits.fill(0)
  keyBits = 0
  gpioBits = 0
  latched = 0
}

/** Whether a keyboard was the last thing used. */
export function usingKeyboard(): boolean {
  return lastKind === 'key'
}

sources.controls.ts:
// The on-screen controls: a D-pad (left/right, or a cross) and up to two
// action buttons, drawn into the cells, with a pause button. On a wide screen
// they sit in panels at both sides (thumbs on a held tablet); on a square or
// tall one in a bar along the bottom. Buttons are at least ~60 px on the
// glass and ~24 px from the screen's edges, where a swipe belongs to the
// frame. The palette indexes they draw with are the kit's UI slots (ui.ts).
import { box, fill, text, textWidth } from './gfx'
import { A, B, DOWN, LEFT, RIGHT, START, UP } from './input'
import { UI_BORDER, UI_EDGE, UI_FACE, UI_ICON, UI_ICON_LIT, UI_LIT, UI_PANEL } from './ui'

const ICON_LEFT = 1
const ICON_RIGHT = 2
const ICON_UP = 3
const ICON_DOWN = 4
const ICON_A = 5
const ICON_B = 6
const ICON_PAUSE = 7

export type Layout = {
  /** The play area, in cells. */
  x: number
  y: number
  w: number
  h: number
  wide: boolean
  /** Buttons: 5 numbers each (bits, x, y, w, h) and an icon. */
  n: number
  b: Int16Array
  icon: Uint8Array
  /** Panels behind the buttons: x, y, w, h each. */
  np: number
  panels: Int16Array
  /** The D-pad's box, which picks a direction by where in it a finger is. */
  dx: number
  dy: number
  dw: number
  dh: number
  dpad: number
  gap: number
  px: number
  labelA: string
  labelB: string
}

/**
 * Where everything goes on a `cols` x `rows` grid of `px`-pixel cells.
 * `dpad` 0 (none), 2 (left and right) or 4 (a cross); `actions` 0, 1 (A) or
 * 2 (A and B); `show` false leaves the whole screen to the game. `sides`
 * false keeps the bar along the bottom on a wide screen too (a wide view).
 */
export function layout(cols: number, rows: number, px: number, dpad: number, actions: number, show: boolean,
    labelA = 'A', labelB = 'B', sides = true): Layout {
  const L: Layout = {
    x: 0, y: 0, w: cols, h: rows, wide: sides && cols >= rows * 1.25, n: 0, b: new Int16Array(40), icon: new Uint8Array(8),
    np: 0, panels: new Int16Array(8), dx: 0, dy: 0, dw: 0, dh: 0, dpad, gap: 1, px, labelA, labelB,
  }
  if (!show) return L
  let bs = Math.max(8, Math.ceil(60 / px)) // a button, in cells
  const edge = Math.max(2, Math.ceil(24 / px)) // kept free along the screen's edges
  const gap = Math.max(1, Math.round(bs / 6))
  L.gap = gap
  if (dpad === 4) bs = Math.max(7, Math.min(bs, Math.floor((rows - 2 * edge) / 3.6)))
  const padW = dpad === 4 ? 3 * bs : dpad === 2 ? 2 * bs + gap : 0
  const padH = dpad === 4 ? 3 * bs : dpad === 2 ? bs : 0
  const actW = actions === 2 ? 2 * bs + gap : actions === 1 ? bs : 0
  const actH = actions === 2 ? bs + (bs >> 1) : actions === 1 ? bs : 0
  const ps = Math.max(6, Math.round(bs * 0.65)) // the pause button
  const add = (bits: number, x: number, y: number, w: number, h: number, icon: number) => {
    const at = L.n * 5
    L.b[at] = bits
    L.b[at + 1] = x
    L.b[at + 2] = y
    L.b[at + 3] = w
    L.b[at + 4] = h
    L.icon[L.n] = icon
    L.n++
  }
  const panel = (x: number, y: number, w: number, h: number) => {
    L.panels.set([x, y, w, h], L.np * 4)
    L.np++
  }
  let padX = 0
  let padY = 0
  let actX = 0
  let actY = 0
  if (L.wide) {
    const side = Math.max(padW, actW, ps) + edge + 2 * gap
    L.x = side
    L.w = cols - 2 * side
    panel(0, 0, side, rows)
    panel(cols - side, 0, side, rows)
    // The thumbs' places: a little below the middle.
    padX = edge
    padY = Math.min(rows - edge - padH, Math.round(rows * 0.58 - padH / 2))
    actX = cols - edge - actW
    actY = Math.min(rows - edge - actH, Math.round(rows * 0.58 - actH / 2))
    add(START, cols - edge - ps, edge, ps, ps, ICON_PAUSE)
  } else {
    const content = Math.max(padH, actH, ps)
    const bar = content + edge + 2 * gap
    L.h = rows - bar
    panel(0, rows - bar, cols, bar)
    padX = edge
    padY = rows - edge - gap - content + ((content - padH) >> 1)
    actX = cols - edge - actW
    actY = rows - edge - gap - content + ((content - actH) >> 1)
    add(START, (cols - ps) >> 1, rows - edge - gap - content + ((content - ps) >> 1), ps, ps, ICON_PAUSE)
  }
  if (dpad === 2) {
    add(LEFT, padX, padY, bs, bs, ICON_LEFT)
    add(RIGHT, padX + bs + gap, padY, bs, bs, ICON_RIGHT)
  } else if (dpad === 4) {
    add(UP, padX + bs, padY, bs, bs, ICON_UP)
    add(LEFT, padX, padY + bs, bs, bs, ICON_LEFT)
    add(RIGHT, padX + 2 * bs, padY + bs, bs, bs, ICON_RIGHT)
    add(DOWN, padX + bs, padY + 2 * bs, bs, bs, ICON_DOWN)
  }
  L.dx = padX
  L.dy = padY
  L.dw = padW
  L.dh = padH
  if (actions === 2) {
    // B up and to the left, A down and to the right, as on a game pad.
    add(B, actX, actY, bs, bs, ICON_B)
    add(A, actX + bs + gap, actY + (bs >> 1), bs, bs, ICON_A)
  } else if (actions === 1) {
    add(A, actX, actY, bs, bs, ICON_A)
  }
  return L
}

/** What a pointer at (x, y) scene pixels presses: action bits, or 0 for the
 *  play area and the bare panels. */
export function hit(L: Layout, x: number, y: number): number {
  const cx = x / L.px
  const cy = y / L.px
  const g = L.gap
  // The D-pad as one pad: a direction by where on it the thumb is, so a
  // thumb rolling across it never falls between two buttons.
  if (L.dpad && cx >= L.dx - g && cx < L.dx + L.dw + g && cy >= L.dy - g && cy < L.dy + L.dh + g) {
    if (L.dpad === 2) return cx < L.dx + L.dw / 2 ? LEFT : RIGHT
    const mx = cx - (L.dx + L.dw / 2)
    const my = cy - (L.dy + L.dh / 2)
    const dead = L.dw / 6
    let bits = 0
    if (mx < -dead) bits |= LEFT
    if (mx > dead) bits |= RIGHT
    if (my < -dead) bits |= UP
    if (my > dead) bits |= DOWN
    return bits
  }
  for (let i = 0; i < L.n; i++) {
    const at = i * 5
    const bits = L.b[at]
    if (bits & (LEFT | RIGHT | UP | DOWN)) continue
    if (cx >= L.b[at + 1] - g && cy >= L.b[at + 2] - g && cx < L.b[at + 1] + L.b[at + 3] + g &&
        cy < L.b[at + 2] + L.b[at + 4] + g) return bits
  }
  return 0
}

/** Panels and every button. */
export function drawControls(L: Layout, held: number) {
  for (let i = 0; i < L.np; i++) {
    const at = i * 4
    const x = L.panels[at]
    const y = L.panels[at + 1]
    const w = L.panels[at + 2]
    const h = L.panels[at + 3]
    fill(x, y, w, h, UI_PANEL)
    // A line along the side that meets the play area.
    if (L.wide) fill(x === 0 ? x + w - 1 : x, y, 1, h, UI_EDGE)
    else fill(x, y, w, 1, UI_EDGE)
  }
  for (let i = 0; i < L.n; i++) drawButton(L, i, (held & L.b[i * 5]) !== 0)
}

/** Draws again only the buttons whose state changed between `was` and `now`. */
export function updateControls(L: Layout, was: number, now: number) {
  const changed = was ^ now
  if (!changed) return
  for (let i = 0; i < L.n; i++) if (changed & L.b[i * 5]) drawButton(L, i, (now & L.b[i * 5]) !== 0)
}

function drawButton(L: Layout, i: number, lit: boolean) {
  const at = i * 5
  const x = L.b[at + 1]
  const y = L.b[at + 2]
  const w = L.b[at + 3]
  const h = L.b[at + 4]
  box(x, y, w, h, lit ? UI_LIT : UI_FACE, UI_BORDER, UI_PANEL)
  const ink = lit ? UI_ICON_LIT : UI_ICON
  const cx = x + (w >> 1)
  const cy = y + (h >> 1) + (lit ? 1 : 0)
  const icon = L.icon[i]
  const r = Math.max(2, Math.round(w * 0.22))
  if (icon <= ICON_DOWN) arrow(icon, cx, cy, r, ink)
  else if (icon === ICON_PAUSE) {
    const bw = Math.max(1, Math.round(w / 7))
    fill(cx - bw - Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
    fill(cx + Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
  } else {
    const label = icon === ICON_A ? L.labelA : L.labelB
    // Letters about half the button's height, as wide as fit.
    let scale = Math.max(1, Math.floor((h * 0.5) / 5 + 0.5))
    while (scale > 1 && textWidth(label, scale) > w - 4) scale--
    text(label, cx - ((textWidth(label, scale) / 2) | 0), cy - ((5 * scale) >> 1), scale, ink)
  }
}

/** A filled triangle pointing `dir`, `r` cells from its tip to its base,
 *  centred on (cx, cy). */
function arrow(dir: number, cx: number, cy: number, r: number, v: number) {
  const half = (r + 1) >> 1
  for (let i = 0; i <= r; i++) {
    // i: how far from the tip; the span widens by one each side per step.
    if (dir === ICON_LEFT) fill(cx - half + i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_RIGHT) fill(cx + half - i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_UP) fill(cx - i, cy - half + i, 2 * i + 1, 1, v)
    else fill(cx - i, cy + half - i, 2 * i + 1, 1, v)
  }
}

sources.ui.ts:
// What the games share besides drawing and input: the palette slots of the
// controls and screens, the contrast rule, the cell size, the fixed-step
// clock, the random numbers, the high score table and the title, pause and
// game over screens. A game's own colors use palette indexes 0..223; the kit
// owns 224..255.
import { box, fill, textCenter, textWidth, title } from './gfx'

export const UI_TITLE = 224 // .. 228, a gradient down the title's letters
export const UI_SHADOW = 229
export const UI_ICON_LIT = 230
export const UI_PANEL = 231
export const UI_EDGE = 232
export const UI_BORDER = 233
export const UI_FACE = 234
export const UI_LIT = 235
export const UI_ICON = 236
export const UI_TEXT = 237
export const UI_DIM = 238
export const UI_BLINK = 239 // text that blinks: its color flips, no cell changes
export const UI_DIALOG = 240
export const UI_DIALOG_EDGE = 241
export const UI_ACCENT = 242
export const UI_GOOD = 243 // a new high score

/** A game's colors for the kit's slots, 0xRRGGBB. */
export type Theme = {
  title: number[] // five, top to bottom
  shadow: number
  panel: number
  edge: number
  border: number
  face: number
  lit: number
  icon: number
  iconLit: number
  text: number
  dim: number
  dialog: number
  dialogEdge: number
  accent: number
  good: number
}

const WHITE = 0xffffff
const BLACK = 0x000000

/** The kit's slots of `pal`, in the theme's colors or in black and white. */
export function uiColors(pal: Uint32Array, t: Theme, hc: boolean) {
  for (let i = 0; i < 5; i++) pal[UI_TITLE + i] = hc ? WHITE : t.title[i]
  pal[UI_SHADOW] = hc ? BLACK : t.shadow
  pal[UI_ICON_LIT] = hc ? BLACK : t.iconLit
  pal[UI_PANEL] = hc ? BLACK : t.panel
  pal[UI_EDGE] = hc ? WHITE : t.edge
  pal[UI_BORDER] = hc ? WHITE : t.border
  pal[UI_FACE] = hc ? BLACK : t.face
  pal[UI_LIT] = hc ? WHITE : t.lit
  pal[UI_ICON] = hc ? WHITE : t.icon
  pal[UI_TEXT] = hc ? WHITE : t.text
  pal[UI_DIM] = hc ? WHITE : t.dim
  pal[UI_BLINK] = hc ? WHITE : t.text
  pal[UI_DIALOG] = hc ? BLACK : t.dialog
  pal[UI_DIALOG_EDGE] = hc ? WHITE : t.dialogEdge
  pal[UI_ACCENT] = hc ? WHITE : t.accent
  pal[UI_GOOD] = hc ? WHITE : t.good
}

/** "Press A" text blinks by its palette entry alone. */
export function blink(pal: Uint32Array, now: number, on: number, off: number) {
  pal[UI_BLINK] = ((now / 450) | 0) & 1 ? off : on
}

// --- settings --------------------------------------------------------------

/** High contrast where the panel shows no color, or when asked. */
export function highContrast(contrast: any, frame: any): boolean {
  const mode = contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && frame.color === false)
}

/** Whether the panel can animate (an LCD, HDMI) rather than e-paper. */
export function fastScreen(frame: any): boolean {
  return frame.fast ?? !frame.paper
}

/** The "Pixel size" setting: a number, or about `across` cells over the
 *  short side for "auto". */
export function cellSize(setting: any, width: number, height: number, across: number): number {
  const asked = Number(setting) | 0
  if (asked >= 1) return Math.min(16, asked)
  return Math.max(2, Math.round(Math.min(width, height) / across))
}

/** One of `allowed`, else the first. */
export function choice(value: any, allowed: string[]): string {
  const s = String(value ?? '')
  return allowed.indexOf(s) >= 0 ? s : allowed[0]
}

// --- the clock ---------------------------------------------------------------

let last = 0
let owed = 0

/**
 * How many fixed steps of `stepMs` to run this frame, from the wall clock, so
 * the game keeps its speed at 12 fps and at 40. At most `cap` (a slow frame
 * slows the game rather than jumping it), none after a long gap (a pause, a
 * sleep).
 */
export function stepsDue(now: number, stepMs: number, cap: number): number {
  let gap = now - last
  last = now
  if (gap < 0 || gap > 400) gap = stepMs
  owed += gap
  let n = (owed / stepMs) | 0
  owed -= n * stepMs
  if (n > cap) {
    n = cap
    owed = 0
  }
  return n
}

/** Start counting from now (a new game, a resume). */
export function clockReset(now: number) {
  last = now
  owed = 0
}

// --- random numbers ----------------------------------------------------------

let seed = 1

export function reseed(s: number) {
  seed = s | 0 || 0x2545f491
}

/** An xorshift32: a 32-bit integer. */
export function rnd(): number {
  seed ^= seed << 13
  seed ^= seed >>> 17
  seed ^= seed << 5
  return seed
}

/** 0 .. n-1. */
export function rint(n: number): number {
  return ((rnd() >>> 0) % n) | 0
}

/** [0, 1). */
export function rfloat(): number {
  return (rnd() >>> 0) / 4294967296
}

// --- high scores -------------------------------------------------------------

/** The top five from the private `highScores` field (a JSON list of numbers). */
export function readScores(raw: any): number[] {
  let list = raw
  if (typeof list === 'string') {
    try {
      list = JSON.parse(list)
    } catch (e) {
      list = null
    }
  }
  const out: number[] = []
  if (Array.isArray(list)) for (const n of list) if (typeof n === 'number' && n > 0) out.push(n | 0)
  out.sort((a, b) => b - a)
  return out.slice(0, 5)
}

/** Puts `score` in the table: its place (0 = best), or -1 when it is not in
 *  the top five. Saves the table when it changed. */
export function addScore(list: number[], score: number): number {
  if (score <= 0) return -1
  let at = 0
  while (at < list.length && list[at] >= score) at++
  if (at >= 5) return -1
  list.splice(at, 0, score | 0)
  if (list.length > 5) list.length = 5
  frameos.setState('highScores', list.slice())
  return at
}

// --- screens -----------------------------------------------------------------

/** A dialog box: a border and a face. */
export function dialog(x: number, y: number, w: number, h: number) {
  fill(x, y, w, h, UI_DIALOG_EDGE)
  fill(x + 1, y + 1, w - 2, h - 2, UI_DIALOG)
}

/** The scale of the font that fits `chars` letters across `width` cells, at
 *  most `max`. */
export function fitScale(chars: number, width: number, max: number): number {
  return Math.max(1, Math.min(max, Math.floor(width / (chars * 4))))
}

/** The high score table, centred on `cx` from `y`: answers the rows it took. */
export function drawScores(list: number[], cx: number, y: number, scale: number, highlight = -1, label = 'HIGH SCORES'): number {
  textCenter(label, cx, y, scale, UI_ACCENT)
  if (!list.length) {
    textCenter('NONE YET', cx, y + 7 * scale, scale, UI_DIM)
    return 12 * scale
  }
  for (let i = 0; i < list.length; i++) {
    const line = String(i + 1) + '. ' + pad(list[i], 7)
    textCenter(line, cx, y + (7 + i * 7) * scale, scale, i === highlight ? UI_GOOD : UI_TEXT)
  }
  return (7 + list.length * 7) * scale
}

function pad(n: number, width: number): string {
  let s = String(n)
  while (s.length < width) s = ' ' + s
  return s
}

// The pause dialog's two buttons, for tapping: x, y, w, h each.
const choiceBoxes = new Int16Array(8)

/**
 * The pause dialog over the play area (x, y, w, h): PAUSED, and Resume and
 * Quit as big buttons. `hint` is a line of the keys, shown where it fits.
 * Another headline, a line under it and other buttons make it another
 * two-way choice (a rematch or the menu).
 */
export function drawPause(x: number, y: number, w: number, h: number, hint: string, head = 'PAUSED', line = '',
    first = 'RESUME', second = 'QUIT') {
  // Rows it takes at text scale s: 3 + 10 (the title, twice as big) + 4 + 11 + 3 + 11 + 3, 7 for the line
  // and 8 for the hint.
  const extra = line ? 7 : 0
  const s = Math.max(1, Math.min(Math.floor((w - 6) / 34), Math.floor((h - 4) / (45 + extra))))
  const ts = Math.max(1, Math.min(4, 2 * s, Math.floor((w - 8) / (head.length * 4))))
  const withHint = hint && h - 4 >= (45 + extra) * s + 8 && textWidth(hint, 1) <= w - 6
  const dw = Math.min(w - 2, Math.max(34 * s, textWidth(head, ts) + 6 * s, textWidth(line, s) + 6 * s,
    withHint ? textWidth(hint, 1) + 6 : 0))
  const dh = (45 + extra) * s + (withHint ? 8 : 0)
  const dx = x + ((w - dw) >> 1)
  const dy = y + ((h - dh) >> 1)
  dialog(dx, dy, dw, dh)
  const cx = dx + (dw >> 1)
  title(head, cx, dy + 3 * s, ts, UI_TITLE, UI_SHADOW)
  const bw = dw - 6 * s
  const bh = 11 * s
  const bx = dx + 3 * s
  let by = dy + 3 * s + 5 * ts + 4 * s
  if (line) {
    textCenter(line, cx, by - s, s, UI_TEXT)
    by += 7 * s
  }
  for (let i = 0; i < 2; i++) {
    box(bx, by, bw, bh, UI_FACE, UI_BORDER, UI_DIALOG)
    textCenter(i === 0 ? first : second, cx, by + 3 * s, s, UI_ICON)
    choiceBoxes[i * 4] = bx
    choiceBoxes[i * 4 + 1] = by
    choiceBoxes[i * 4 + 2] = bw
    choiceBoxes[i * 4 + 3] = bh
    by += bh + 3 * s
  }
  if (withHint) textCenter(hint, cx, dy + dh - 7, 1, UI_DIM)
}

/** Which of the pause dialog's buttons a tap at cell (cx, cy) is on: 1 Resume, 2 Quit, 0 neither. */
export function pauseChoice(cx: number, cy: number): number {
  for (let i = 0; i < 2; i++) {
    const at = i * 4
    if (cx >= choiceBoxes[at] && cy >= choiceBoxes[at + 1] && cx < choiceBoxes[at] + choiceBoxes[at + 2] &&
        cy < choiceBoxes[at + 1] + choiceBoxes[at + 3]) return i + 1
  }
  return 0
}

/**
 * Game over in a dialog over (x, y, w, h): the headline, a line or two about
 * the game, a new high score's place, as much of the table as fits, and
 * "tap" once `ready`.
 */
export function drawGameOver(x: number, y: number, w: number, h: number, head: string, lines: string[],
    rank: number, list: number[], ready: boolean, prompt = 'TAP OR PRESS A') {
  let widest = 15
  for (const line of lines) if (line.length > widest) widest = line.length
  const s = Math.max(1, Math.min(Math.floor((w - 6) / (widest * 4 + 4)), Math.floor((h - 4) / 60)))
  const big = Math.max(1, Math.min(2 * s, Math.floor((w - 8) / (head.length * 4))))
  // Rows: padding, the headline, the lines, the high score line, "tap".
  let need = 3 * s + 5 * big + 4 * s + lines.length * 7 * s + (rank >= 0 ? 7 * s : 0) + 9 * s
  const room = h - 4 - need - 7 * s
  const shown = Math.max(0, Math.min(list.length, Math.floor(room / (7 * s))))
  if (shown) need += (7 + shown * 7) * s + 2 * s
  const dw = Math.min(w - 2, Math.max(textWidth(head, big) + 8 * s, (widest * 4 + 4) * s))
  const dh = Math.min(h - 2, need)
  const dx = x + ((w - dw) >> 1)
  const dy = y + ((h - dh) >> 1)
  dialog(dx, dy, dw, dh)
  const cx = dx + (dw >> 1)
  title(head, cx, dy + 3 * s, big, UI_TITLE, UI_SHADOW)
  let ty = dy + 3 * s + 5 * big + 4 * s
  for (const line of lines) {
    textCenter(line, cx, ty, s, UI_TEXT)
    ty += 7 * s
  }
  if (rank >= 0) {
    textCenter(rank === 0 ? 'NEW HIGH SCORE!' : 'A HIGH SCORE!', cx, ty, s, UI_GOOD)
    ty += 7 * s
  }
  if (shown) {
    ty += 2 * s
    drawScores(list.slice(0, shown), cx, ty, s, rank)
  }
  if (ready) textCenter(prompt, cx, dy + dh - 8 * s, s, UI_BLINK)
}

/** For a screen that cannot animate (e-paper): what the game is and what it needs. */
export function drawSlowCard(cols: number, rows: number, name: string, about: string[], list: number[] | null) {
  fill(0, 0, cols, rows, UI_PANEL)
  const scale = fitScale(name.length + 2, cols - 4, 6)
  const small = fitScale(30, cols - 4, 3)
  // Everything in the middle of the screen.
  const tall = 8 * scale + about.length * 7 * small + (list ? (11 + Math.max(1, list.length) * 7) * small : 0)
  let y = Math.max(2, (rows - tall) >> 1)
  title(name, cols >> 1, y, scale, UI_TITLE, UI_SHADOW)
  y += 8 * scale
  for (const line of about) {
    textCenter(line, cols >> 1, y, small, UI_TEXT)
    y += 7 * small
  }
  y += 4 * small
  if (list) drawScores(list, cols >> 1, y, small)
}
